INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 28, 'theory', 'Quiz: /dev/kvm and a tiny guest');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 28, 0, 'What must KVM_GET_API_VERSION return for the program to carry on?', '["Any value of at least 12", "Any positive number", "Exactly 12", "Exactly 1"]', 2, 'The documentation demands refusing to work with any value but 12: the interface is stable, and new features are added as extensions that are checked separately.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 28, 1, 'On which descriptor is KVM_CREATE_VCPU issued?', '["On the machine descriptor returned by KVM_CREATE_VM", "On the system descriptor of /dev/kvm", "On another processor''s descriptor", "On any of the three levels"]', 0, 'The system descriptor creates machines, the machine descriptor creates processors, and KVM_RUN is issued on the processor descriptor. A request of the wrong level is rejected by the kernel.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 28, 2, 'Why must the kvm_run area be mapped with the size from KVM_GET_VCPU_MMAP_SIZE and not sizeof(struct kvm_run)?', '["Because sizeof does not work with kernel structures in C", "Because the kernel checks the program''s signature", "Because the size is independent of architecture and version", "Because the area includes more than the structure, for example the port data page on x86"]', 3, 'The kernel reports the size of the whole area. On x86 a port data page and a coalesced MMIO page follow the structure, and the data of KVM_EXIT_IO is addressed by an offset inside the area.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 28, 3, 'KVM_RUN returned -1 and errno is EINTR. What does the monitor do?', '["Treats the guest as crashed", "Calls KVM_RUN again", "Closes the processor descriptor", "Reads run->exit_reason as the cause of a guest failure"]', 1, 'EINTR means an unmasked signal interrupted the request, not that the guest broke. The guest''s state is kept, so KVM_RUN is simply called again.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 28, 4, 'What does a result of 0 from KVM_CHECK_EXTENSION mean?', '["The call failed: the cause is in errno", "The feature is enabled and carries no data", "The feature is not supported by this kernel", "The kernel is older than API version 12"]', 2, 'Zero means unsupported, a positive number means supported and sometimes carries data. A failed call looks different: -1 and errno.');
